"""Tests for the minimal example package."""

from pkg import greet
from pkg.core import greet as core_greet


def test_greet_returns_greeting():
    assert greet("Alice") == "Hello, Alice!"


def test_greet_is_exported_from_package():
    assert greet is core_greet


def test_greet_with_empty_name():
    assert greet("") == "Hello, !"
